const heap = {
  root: ['a', 'c'],
  a: ['b'],
  b: [],
  c: [],
  x: ['y'],
  y: ['x'],
};
const roots = ['root'];

const reachable = new Set();
const queue = [...roots];
while (queue.length) {
  const id = queue.shift();
  if (reachable.has(id)) continue;
  reachable.add(id);
  for (const next of heap[id]) queue.push(next);
}

const all = Object.keys(heap);
const live = all.filter((id) => reachable.has(id)).sort();
const garbage = all.filter((id) => !reachable.has(id)).sort();
console.log('live=' + live.join(',') + ' garbage=' + garbage.join(','));

